async function assessWhenReady({wait = sleep, maxPolls = 260, queuedGraceSeconds = graceSeconds(config), ...options}) {
  const schedule = pollSchedule(queuedGraceSeconds);
  for (let attempt = 0; attempt < maxPolls; attempt++) {
    let result;
    try {result = await withRateLimit(() => assess(options), {wait, report: options.report});}
    catch (error) {if (error instanceof RateLimitHold) return rateLimited(options.context, error); throw error;}
    if (result.decision !== 'pending_technical') return result;
    const {stalled, delay} = schedule(result.verification);
    if (stalled) return {...result, reason: WAITING_REASON};
    await wait(delay);
  }
  throw new Error('Verification did not finish before the assessment deadline');
}

// The bounded replacement for a consumer's inline polling loop. It holds a
// runner only while verification is running. Verification that has not started
// within the queue grace ends the step cleanly with verified=false so later
// steps are skipped and the run is reassessed when verification completes.
async function awaitVerification({github, context, core, expectedHead, wait = sleep, maxPolls = 120, queuedGraceSeconds = graceSeconds(config)}) {
  const pull_number = numberFor(context);
  const schedule = pollSchedule(queuedGraceSeconds);
  // Only a push event's commit is the PR head; comment and manual events run on
  // the default branch, so they bind to the head observed when the wait starts.
  let expected = expectedHead || (context.eventName === 'push' ? context.sha : null);
  const limited = call => withRateLimit(call, {wait, report: message => core.info(message)});
  // Every way the wait can end without a green verification publishes an assessment, so the write-capable job
  // can post a visible notice (pending, rate-limited or failed) and hold instead of failing silently.
  const payloadPr = context.payload.pull_request;
  const publish = (pr, extra) => core.setOutput('assessment', JSON.stringify({version: 2, number: pull_number,
    head_sha: pr?.head.sha ?? expected ?? payloadPr?.head?.sha ?? '', base_sha: pr?.base.sha ?? payloadPr?.base?.sha ?? '', ...extra}));
  let pr;
  for (let attempt = 0; attempt < maxPolls; attempt++) {
    let result;
    try {
      ({data: pr} = await limited(() => github.rest.pulls.get({...context.repo, pull_number})));
      expected ??= pr.head.sha;
      if (pr.state !== 'open' || pr.draft || pr.head.sha !== expected) {
        throw new Error('PR closed, became draft, or changed while verification was pending');
      }

  const existing = comments.find(item => item.user?.login === 'github-actions[bot]' && item.body.startsWith(`${MARKER}\n`));
  const text = body(assessment, runUrl);
  if (existing) await github.rest.issues.updateComment({...repo, comment_id: existing.id, body: text});
  else await github.rest.issues.createComment({...repo, issue_number, body: text});
}

const PENDING = '<!-- clouseau-review-pending -->';

function pendingBody(assessment, runUrl) {
  const reason = String(assessment.reason ?? '').replaceAll('@', '').replace(/\s+/g, ' ').slice(0, 500);
  return `${PENDING}\n## Clouseau review pending\n\nRevision \`${String(assessment.head_sha).slice(0, 12)}\` is waiting for PR verification ` +
    `(tests, exact coverage and package build, state: ${String(assessment.verification ?? 'unknown')}). No decision has been made and nothing is approved or merged. ` +
    `The review runs again automatically when verification completes; no action is needed.\n\n${reason}\n\nWorkflow run: ${runUrl}`;
}

// One short comment per PR, updated in place; replaced by a resolution line once a decision exists.
async function postPending({github, context, assessment}) {
  const repo = context.repo; const issue_number = assessment.number;
  const runUrl = `https://github.com/${repo.owner}/${repo.repo}/actions/runs/${context.runId}`;
  const comments = await github.paginate(github.rest.issues.listComments, {...repo, issue_number, per_page: 100});
  const existing = comments.find(item => item.user?.login === 'github-actions[bot]' && item.body.startsWith(`${PENDING}\n`));
  const text = pendingBody(assessment, runUrl);
  if (existing) await github.rest.issues.updateComment({...repo, comment_id: existing.id, body: text});
  else await github.rest.issues.createComment({...repo, issue_number, body: text});
}

async function resolvePending({github, context, number}) {
  const repo = context.repo;
  const comments = await github.paginate(github.rest.issues.listComments, {...repo, issue_number: number, per_page: 100});
  const existing = comments.find(item => item.user?.login === 'github-actions[bot]' && item.body.startsWith(`${PENDING}\n`) && !item.body.includes('Resolved'));
  if (existing) await github.rest.issues.updateComment({...repo, comment_id: existing.id, body: `${PENDING}\n## Clouseau review pending\n\nResolved: this pending state has ended; see the latest Clouseau result.`});
}

function annotate({core, assessment}) {
  if (assessment.decision === 'review_incomplete') {
    core.warning(`Clouseau review incomplete (${assessment.cause || 'evidence_incomplete'}): ${assessment.reason}`);
  }
}

